villes = ["Reims", "Metz", "Nancy", "Strasbourg"]
pluie = [
    [45, 38, 52],
    [50, 42, 55],
    [48, 40, 50],
    [42, 35, 48]
]

def moyenne_ligne(mat, i):
    total = 0
    for val in mat[i]:
        total = total + val
    return total / len(mat[i])

